import { NextResponse } from 'next/server'
import type { NextRequest } from 'next/server'

// No `matcher` is exported, so this runs on every request (pages, API routes,
// static assets, image optimization, etc).
export function proxy(request: NextRequest) {
  const { method, nextUrl } = request
  console.log(
    `[${new Date().toISOString()}] ${method} ${nextUrl.pathname}${nextUrl.search}`
  )
  return NextResponse.next()
}

